export type EventMap = Record<string, unknown>;
export type EventListener<T> = (event: T) => void;

export class EventBus<Events extends EventMap = EventMap> {
  private readonly listeners = new Map<keyof Events, Set<EventListener<unknown>>>();

  on<K extends keyof Events>(type: K, listener: EventListener<Events[K]>): () => void {
    let bucket = this.listeners.get(type);
    if (!bucket) {
      bucket = new Set();
      this.listeners.set(type, bucket);
    }
    bucket.add(listener as EventListener<unknown>);
    return () => bucket?.delete(listener as EventListener<unknown>);
  }

  emit<K extends keyof Events>(type: K, event: Events[K]): void {
    const bucket = this.listeners.get(type);
    if (!bucket) return;
    for (const listener of [...bucket]) listener(event);
  }

  clear(type?: keyof Events): void {
    if (type === undefined) this.listeners.clear();
    else this.listeners.delete(type);
  }
}
