export type RenderCommand =
  | { type: 'sprite'; asset: string; x: number; y: number; rotation: number; scale: number; layer: number; tint?: string }
  | { type: 'circle'; x: number; y: number; radius: number; fill: string; layer: number }
  | { type: 'line'; x1: number; y1: number; x2: number; y2: number; width: number; stroke: string; layer: number }
  | { type: 'text'; text: string; x: number; y: number; style: string; layer: number };

export class CommandBuffer {
  private commands: RenderCommand[] = [];
  push(command: RenderCommand): void { this.commands.push(command); }
  drain(): RenderCommand[] {
    this.commands.sort((a, b) => a.layer - b.layer);
    const output = this.commands;
    this.commands = [];
    return output;
  }
  get size(): number { return this.commands.length; }
}
