import { EventBus } from './EventBus.js';
import { FixedStepClock } from './FixedStepClock.js';

export interface EngineLifecycle {
  shouldUpdate(): boolean;
  fixedUpdate(delta: number): void;
  render(alpha: number, frameDelta: number): void;
}

export interface EngineOptions {
  fixedDelta?: number;
  maxCatchUpSteps?: number;
  requestFrame?: (callback: FrameRequestCallback) => number;
  cancelFrame?: (id: number) => void;
}

export interface EngineEvents {
  started: { at: number };
  stopped: { at: number };
  frameDrop: { seconds: number };
  [key: string]: unknown;
}

export class Engine {
  readonly clock: FixedStepClock;
  readonly events = new EventBus<EngineEvents>();
  private readonly requestFrame: (callback: FrameRequestCallback) => number;
  private readonly cancelFrame: (id: number) => void;
  private frameId: number | null = null;
  private lifecycle: EngineLifecycle | null = null;
  private running = false;
  private previousFrameMs: number | null = null;

  constructor(options: EngineOptions = {}) {
    this.clock = new FixedStepClock(options.fixedDelta, options.maxCatchUpSteps);
    this.requestFrame = options.requestFrame ?? ((callback) => requestAnimationFrame(callback));
    this.cancelFrame = options.cancelFrame ?? ((id) => cancelAnimationFrame(id));
  }

  start(lifecycle: EngineLifecycle): void {
    if (this.running) return;
    this.lifecycle = lifecycle;
    this.running = true;
    this.previousFrameMs = null;
    this.clock.reset();
    this.events.emit('started', { at: Date.now() });
    this.frameId = this.requestFrame(this.frame);
  }

  stop(): void {
    if (!this.running) return;
    this.running = false;
    if (this.frameId !== null) this.cancelFrame(this.frameId);
    this.frameId = null;
    this.events.emit('stopped', { at: Date.now() });
  }

  isRunning(): boolean { return this.running; }

  frameOnce(nowMs: number): void {
    const lifecycle = this.lifecycle;
    if (!lifecycle) return;
    const frameDelta = this.previousFrameMs === null ? 0 : Math.min(0.25, Math.max(0, (nowMs - this.previousFrameMs) / 1000));
    this.previousFrameMs = nowMs;
    const result = this.clock.advance(nowMs, (delta) => lifecycle.fixedUpdate(delta), lifecycle.shouldUpdate());
    if (result.droppedSeconds > 0) this.events.emit('frameDrop', { seconds: result.droppedSeconds });
    lifecycle.render(result.alpha, frameDelta);
  }

  private readonly frame = (nowMs: number): void => {
    if (!this.running) return;
    this.frameOnce(nowMs);
    this.frameId = this.requestFrame(this.frame);
  };
}
