export type Entity = number;
export type ComponentKey<T> = symbol & { readonly __component?: T };

export function component<T>(name: string): ComponentKey<T> {
  return Symbol(name) as ComponentKey<T>;
}

export interface System {
  readonly name: string;
  readonly order: number;
  update(world: World, delta: number): void;
}

export class World {
  private nextEntity = 1;
  private readonly alive = new Set<Entity>();
  private readonly stores = new Map<symbol, Map<Entity, unknown>>();
  private readonly systems: System[] = [];

  create(): Entity {
    const entity = this.nextEntity++;
    this.alive.add(entity);
    return entity;
  }

  destroy(entity: Entity): boolean {
    if (!this.alive.delete(entity)) return false;
    for (const store of this.stores.values()) store.delete(entity);
    return true;
  }

  hasEntity(entity: Entity): boolean { return this.alive.has(entity); }

  set<T>(entity: Entity, key: ComponentKey<T>, value: T): T {
    if (!this.alive.has(entity)) throw new Error(`Unknown entity ${entity}`);
    let store = this.stores.get(key);
    if (!store) { store = new Map(); this.stores.set(key, store); }
    store.set(entity, value);
    return value;
  }

  get<T>(entity: Entity, key: ComponentKey<T>): T | undefined {
    return this.stores.get(key)?.get(entity) as T | undefined;
  }

  remove<T>(entity: Entity, key: ComponentKey<T>): boolean {
    return this.stores.get(key)?.delete(entity) ?? false;
  }

  query<A>(a: ComponentKey<A>): Array<[Entity, A]>;
  query<A, B>(a: ComponentKey<A>, b: ComponentKey<B>): Array<[Entity, A, B]>;
  query(...keys: symbol[]): unknown[] {
    if (!keys.length) return [];
    const first = this.stores.get(keys[0]!);
    if (!first) return [];
    const result: unknown[] = [];
    for (const [entity, value] of first) {
      const row: unknown[] = [entity, value];
      let matches = true;
      for (let i = 1; i < keys.length; i++) {
        const next = this.stores.get(keys[i]!)?.get(entity);
        if (next === undefined) { matches = false; break; }
        row.push(next);
      }
      if (matches) result.push(row);
    }
    return result;
  }

  addSystem(system: System): void {
    if (this.systems.some((entry) => entry.name === system.name)) throw new Error(`Duplicate system ${system.name}`);
    this.systems.push(system);
    this.systems.sort((left, right) => left.order - right.order || left.name.localeCompare(right.name));
  }

  update(delta: number): void {
    for (const system of this.systems) system.update(this, delta);
  }

  clear(): void {
    this.alive.clear();
    this.stores.clear();
    this.nextEntity = 1;
  }
}
