export type AudioBusName = 'master' | 'music' | 'sfx' | 'ui' | 'voice';

export class AudioMixer {
  private readonly gains = new Map<AudioBusName, number>([
    ['master', 1], ['music', 0.35], ['sfx', 1], ['ui', 0.8], ['voice', 1]
  ]);
  private muted = false;

  setGain(bus: AudioBusName, gain: number): void { this.gains.set(bus, Math.max(0, Math.min(1, gain))); }
  getGain(bus: AudioBusName): number { return this.muted ? 0 : (this.gains.get(bus) ?? 1) * (this.gains.get('master') ?? 1); }
  setMuted(muted: boolean): void { this.muted = muted; }
  isMuted(): boolean { return this.muted; }
}
