export interface KeyValueStorage {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

export interface SaveEnvelope<T> { version: number; savedAt: number; data: T; }
export type Migration = (data: unknown) => unknown;

export class VersionedSaveStore {
  private readonly migrations = new Map<number, Migration>();
  private readonly storage: KeyValueStorage;
  private readonly namespace: string;
  constructor(storage: KeyValueStorage, namespace: string) {
    this.storage = storage;
    this.namespace = namespace;
  }

  addMigration(fromVersion: number, migration: Migration): void {
    if (this.migrations.has(fromVersion)) throw new Error(`Migration ${fromVersion} already exists`);
    this.migrations.set(fromVersion, migration);
  }

  save<T>(slot: string, version: number, data: T): SaveEnvelope<T> {
    const envelope = { version, savedAt: Date.now(), data };
    this.storage.setItem(this.key(slot), JSON.stringify(envelope));
    return envelope;
  }

  load<T>(slot: string, targetVersion: number, validate: (data: unknown) => data is T): SaveEnvelope<T> | null {
    const raw = this.storage.getItem(this.key(slot));
    if (!raw) return null;
    let envelope: SaveEnvelope<unknown>;
    try { envelope = JSON.parse(raw) as SaveEnvelope<unknown>; }
    catch { throw new Error(`Corrupt save slot: ${slot}`); }
    while (envelope.version < targetVersion) {
      const migration = this.migrations.get(envelope.version);
      if (!migration) throw new Error(`Missing migration ${envelope.version} -> ${envelope.version + 1}`);
      envelope = { ...envelope, version: envelope.version + 1, data: migration(envelope.data) };
    }
    if (envelope.version !== targetVersion || !validate(envelope.data)) throw new Error(`Invalid save slot: ${slot}`);
    return envelope as SaveEnvelope<T>;
  }

  remove(slot: string): void { this.storage.removeItem(this.key(slot)); }
  private key(slot: string): string { return `${this.namespace}:${slot}`; }
}
