export type ContentKind = 'map' | 'unit' | 'weapon' | 'ability' | 'mission' | 'audio' | 'sprite';

export interface ContentRecord { id: string; version?: number; [key: string]: unknown; }
export type ContentValidator<T extends ContentRecord> = (value: unknown) => value is T;

export class ContentRegistry {
  private readonly records = new Map<ContentKind, Map<string, ContentRecord>>();
  private readonly validators = new Map<ContentKind, ContentValidator<ContentRecord>>();

  setValidator<T extends ContentRecord>(kind: ContentKind, validator: ContentValidator<T>): void {
    this.validators.set(kind, validator as ContentValidator<ContentRecord>);
  }

  register<T extends ContentRecord>(kind: ContentKind, value: T): T {
    if (!value || typeof value.id !== 'string' || !/^[a-z0-9][a-z0-9_-]*$/i.test(value.id)) {
      throw new Error(`Invalid ${kind} id`);
    }
    const id = value.id;
    const validator = this.validators.get(kind);
    if (validator && !validator(value as unknown)) throw new Error(`Invalid ${kind} definition: ${id}`);
    let bucket = this.records.get(kind);
    if (!bucket) { bucket = new Map(); this.records.set(kind, bucket); }
    if (bucket.has(value.id)) throw new Error(`Duplicate ${kind}: ${value.id}`);
    bucket.set(value.id, Object.freeze({ ...value }) as ContentRecord);
    return value;
  }

  get<T extends ContentRecord>(kind: ContentKind, id: string): T | undefined {
    return this.records.get(kind)?.get(id) as T | undefined;
  }

  require<T extends ContentRecord>(kind: ContentKind, id: string): T {
    const value = this.get<T>(kind, id);
    if (!value) throw new Error(`Missing ${kind}: ${id}`);
    return value;
  }

  list<T extends ContentRecord>(kind: ContentKind): readonly T[] {
    return [...(this.records.get(kind)?.values() ?? [])] as T[];
  }

  validateReferences(kind: ContentKind, ids: Iterable<string>): string[] {
    const missing: string[] = [];
    for (const id of ids) if (!this.records.get(kind)?.has(id)) missing.push(id);
    return missing;
  }
}
