export interface ReplayFrame<Input> { tick: number; input: Input; checksum?: number; }
export interface ReplayFile<Input> { engineVersion: number; seed: number; contentHash: string; frames: ReplayFrame<Input>[]; }

export class ReplayRecorder<Input> {
  private readonly frames: ReplayFrame<Input>[] = [];
  readonly engineVersion: number;
  readonly seed: number;
  readonly contentHash: string;
  constructor(engineVersion: number, seed: number, contentHash: string) {
    this.engineVersion = engineVersion;
    this.seed = seed;
    this.contentHash = contentHash;
  }

  record(tick: number, input: Input, checksum?: number): void {
    if (!Number.isInteger(tick) || tick < 0) throw new Error('Replay tick must be a non-negative integer');
    const previous = this.frames[this.frames.length - 1];
    if (previous && tick <= previous.tick) throw new Error('Replay ticks must be strictly increasing');
    const frame: ReplayFrame<Input> = checksum === undefined ? { tick, input } : { tick, input, checksum };
    this.frames.push(structuredClone(frame));
  }

  finish(): ReplayFile<Input> {
    return { engineVersion: this.engineVersion, seed: this.seed, contentHash: this.contentHash, frames: structuredClone(this.frames) };
  }
}

export class ReplayPlayer<Input> {
  private cursor = 0;
  readonly replay: ReplayFile<Input>;
  constructor(replay: ReplayFile<Input>) { this.replay = replay; }
  inputsAt(tick: number): ReplayFrame<Input>[] {
    const frames: ReplayFrame<Input>[] = [];
    while (this.cursor < this.replay.frames.length && this.replay.frames[this.cursor]!.tick <= tick) {
      const frame = this.replay.frames[this.cursor++]!;
      if (frame.tick === tick) frames.push(frame);
    }
    return frames;
  }
  reset(): void { this.cursor = 0; }
}

export function checksumNumbers(values: Iterable<number>): number {
  let hash = 0x811c9dc5;
  for (const value of values) {
    const scaled = Math.round(value * 1000) | 0;
    hash ^= scaled;
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
}
