export type ActionState = 'pressed' | 'held' | 'released' | 'idle';

export class ActionInput {
  private readonly bindings = new Map<string, Set<string>>();
  private readonly down = new Set<string>();
  private readonly pressed = new Set<string>();
  private readonly released = new Set<string>();

  bind(action: string, ...codes: string[]): void {
    if (!action || !codes.length) throw new Error('Action and at least one code are required');
    this.bindings.set(action, new Set(codes));
  }

  setCode(code: string, isDown: boolean): void {
    if (isDown && !this.down.has(code)) this.pressed.add(code);
    if (!isDown && this.down.has(code)) this.released.add(code);
    if (isDown) this.down.add(code); else this.down.delete(code);
  }

  state(action: string): ActionState {
    const codes = this.bindings.get(action);
    if (!codes) return 'idle';
    if ([...codes].some((code) => this.pressed.has(code))) return 'pressed';
    if ([...codes].some((code) => this.released.has(code))) return 'released';
    if ([...codes].some((code) => this.down.has(code))) return 'held';
    return 'idle';
  }

  value(action: string): number { return this.state(action) === 'idle' || this.state(action) === 'released' ? 0 : 1; }
  endFrame(): void { this.pressed.clear(); this.released.clear(); }
  reset(): void { this.down.clear(); this.endFrame(); }
}
